import React from 'react';
import './App.css';
import Home from './Pages/Home';
import Signup from './Pages/Signup';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';

function App() {
  return (
    <div>
      <Router>
        <Route path='/'>
        <Home />
        </Route>
        <Route path="/signup"> element={<Signup />} </Route>
      </Router>
    </div>
  );
}

export default App;
